effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _viewport_ratio acProporcaoDoNode
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec3 u_xlat7;
vec2 u_xlat13;
float u_xlat18;
float u_xlat19;
void main()
{
    u_xlat0.xyz = _background_color.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat0.xyz = _background_color.xyz * u_xlat0.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat1.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat13.xy = vec2(_viewport_ratio.x, _viewport_ratio.y) * _scale.xy;
    u_xlat1.xy = u_xlat1.xy * u_xlat13.xy;
    u_xlat1.xy = u_xlat1.xy * vec2(10.0, 10.0) + vec2(_offset.x, _offset.y);
    u_xlat1.xy = u_xlat1.xy + vec2(0.5, 0.5);
    u_xlat1.z = _evolution;
    u_xlat2.x = dot(u_xlat1.xyz, vec3(-2.0, 3.0, 1.0));
    u_xlat2.y = dot(u_xlat1.xyz, vec3(-1.0, -2.0, 2.0));
    u_xlat2.z = dot(u_xlat1.xzy, vec3(2.0, 2.0, 1.0));
    u_xlat1.xyz = u_xlat2.xyz * vec3(0.400000006, 0.400000006, 0.400000006);
    u_xlat2.xyz = fract(u_xlat1.xyz);
    u_xlat2.xyz = (-u_xlat2.xyz) + vec3(0.5, 0.5, 0.5);
    u_xlat18 = dot(u_xlat2.xyz, u_xlat2.xyz);
    u_xlat18 = sqrt(u_xlat18);
    u_xlat2.x = dot(u_xlat1.xyz, vec3(-2.0, 3.0, 1.0));
    u_xlat2.y = dot(u_xlat1.xyz, vec3(-1.0, -2.0, 2.0));
    u_xlat2.z = dot(u_xlat1.xzy, vec3(2.0, 2.0, 1.0));
    u_xlat1.xyz = u_xlat2.xyz * vec3(0.300000012, 0.300000012, 0.300000012);
    u_xlat2.xyz = fract(u_xlat1.xyz);
    u_xlat2.xyz = (-u_xlat2.xyz) + vec3(0.5, 0.5, 0.5);
    u_xlat19 = dot(u_xlat2.xyz, u_xlat2.xyz);
    u_xlat19 = sqrt(u_xlat19);
    u_xlat18 = min(u_xlat18, u_xlat19);
    u_xlat2.x = dot(u_xlat1.xyz, vec3(-2.0, 3.0, 1.0));
    u_xlat2.y = dot(u_xlat1.xyz, vec3(-1.0, -2.0, 2.0));
    u_xlat2.z = dot(u_xlat1.xzy, vec3(2.0, 2.0, 1.0));
    u_xlat1.xyz = u_xlat2.xyz * vec3(0.200000003, 0.200000003, 0.200000003);
    u_xlat2.xyz = fract(u_xlat1.xyz);
    u_xlat2.xyz = (-u_xlat2.xyz) + vec3(0.5, 0.5, 0.5);
    u_xlat19 = dot(u_xlat2.xyz, u_xlat2.xyz);
    u_xlat19 = sqrt(u_xlat19);
    u_xlat2.x = min(u_xlat18, u_xlat19);
    u_xlat3.x = dot(u_xlat1.xyz, vec3(-2.0, 3.0, 1.0));
    u_xlat3.y = dot(u_xlat1.xyz, vec3(-1.0, -2.0, 2.0));
    u_xlat3.z = dot(u_xlat1.xzy, vec3(2.0, 2.0, 1.0));
    u_xlat1.xyz = u_xlat3.xyz * vec3(0.400000006, 0.400000006, 0.400000006);
    u_xlat3.xyz = fract(u_xlat1.xyz);
    u_xlat3.xyz = (-u_xlat3.xyz) + vec3(0.5, 0.5, 0.5);
    u_xlat18 = dot(u_xlat3.xyz, u_xlat3.xyz);
    u_xlat18 = sqrt(u_xlat18);
    u_xlat3.x = dot(u_xlat1.xyz, vec3(-2.0, 3.0, 1.0));
    u_xlat3.y = dot(u_xlat1.xyz, vec3(-1.0, -2.0, 2.0));
    u_xlat3.z = dot(u_xlat1.xzy, vec3(2.0, 2.0, 1.0));
    u_xlat1.xyz = u_xlat3.xyz * vec3(0.300000012, 0.300000012, 0.300000012);
    u_xlat3.xyz = fract(u_xlat1.xyz);
    u_xlat3.xyz = (-u_xlat3.xyz) + vec3(0.5, 0.5, 0.5);
    u_xlat19 = dot(u_xlat3.xyz, u_xlat3.xyz);
    u_xlat19 = sqrt(u_xlat19);
    u_xlat18 = min(u_xlat18, u_xlat19);
    u_xlat3.x = dot(u_xlat1.xyz, vec3(-2.0, 3.0, 1.0));
    u_xlat3.y = dot(u_xlat1.xyz, vec3(-1.0, -2.0, 2.0));
    u_xlat3.z = dot(u_xlat1.xzy, vec3(2.0, 2.0, 1.0));
    u_xlat1.xyz = u_xlat3.xyz * vec3(0.200000003, 0.200000003, 0.200000003);
    u_xlat3.xyz = fract(u_xlat1.xyz);
    u_xlat3.xyz = (-u_xlat3.xyz) + vec3(0.5, 0.5, 0.5);
    u_xlat19 = dot(u_xlat3.xyz, u_xlat3.xyz);
    u_xlat19 = sqrt(u_xlat19);
    u_xlat2.y = min(u_xlat18, u_xlat19);
    u_xlat3.x = dot(u_xlat1.xyz, vec3(-2.0, 3.0, 1.0));
    u_xlat3.y = dot(u_xlat1.xyz, vec3(-1.0, -2.0, 2.0));
    u_xlat3.z = dot(u_xlat1.xzy, vec3(2.0, 2.0, 1.0));
    u_xlat1.xyz = u_xlat3.xyz * vec3(0.400000006, 0.400000006, 0.400000006);
    u_xlat3.xyz = fract(u_xlat1.xyz);
    u_xlat3.xyz = (-u_xlat3.xyz) + vec3(0.5, 0.5, 0.5);
    u_xlat18 = dot(u_xlat3.xyz, u_xlat3.xyz);
    u_xlat18 = sqrt(u_xlat18);
    u_xlat3.x = dot(u_xlat1.xyz, vec3(-2.0, 3.0, 1.0));
    u_xlat3.y = dot(u_xlat1.xyz, vec3(-1.0, -2.0, 2.0));
    u_xlat3.z = dot(u_xlat1.xzy, vec3(2.0, 2.0, 1.0));
    u_xlat1.xyz = u_xlat3.xyz * vec3(0.300000012, 0.300000012, 0.300000012);
    u_xlat3.xyz = fract(u_xlat1.xyz);
    u_xlat3.xyz = (-u_xlat3.xyz) + vec3(0.5, 0.5, 0.5);
    u_xlat19 = dot(u_xlat3.xyz, u_xlat3.xyz);
    u_xlat19 = sqrt(u_xlat19);
    u_xlat18 = min(u_xlat18, u_xlat19);
    u_xlat3.x = dot(u_xlat1.xyz, vec3(-2.0, 3.0, 1.0));
    u_xlat3.y = dot(u_xlat1.xyz, vec3(-1.0, -2.0, 2.0));
    u_xlat3.z = dot(u_xlat1.xzy, vec3(2.0, 2.0, 1.0));
    u_xlat1.xyz = u_xlat3.xyz * vec3(0.200000003, 0.200000003, 0.200000003);
    u_xlat3.xyz = fract(u_xlat1.xyz);
    u_xlat3.xyz = (-u_xlat3.xyz) + vec3(0.5, 0.5, 0.5);
    u_xlat19 = dot(u_xlat3.xyz, u_xlat3.xyz);
    u_xlat19 = sqrt(u_xlat19);
    u_xlat2.z = min(u_xlat18, u_xlat19);
    u_xlat3.x = dot(u_xlat1.xyz, vec3(-2.0, 3.0, 1.0));
    u_xlat3.y = dot(u_xlat1.xyz, vec3(-1.0, -2.0, 2.0));
    u_xlat3.z = dot(u_xlat1.xzy, vec3(2.0, 2.0, 1.0));
    u_xlat1.xyz = u_xlat3.xyz * vec3(0.400000006, 0.400000006, 0.400000006);
    u_xlat3.xyz = fract(u_xlat1.xyz);
    u_xlat3.xyz = (-u_xlat3.xyz) + vec3(0.5, 0.5, 0.5);
    u_xlat18 = dot(u_xlat3.xyz, u_xlat3.xyz);
    u_xlat18 = sqrt(u_xlat18);
    u_xlat3.x = dot(u_xlat1.xyz, vec3(-2.0, 3.0, 1.0));
    u_xlat3.y = dot(u_xlat1.xyz, vec3(-1.0, -2.0, 2.0));
    u_xlat3.z = dot(u_xlat1.xzy, vec3(2.0, 2.0, 1.0));
    u_xlat1.xyz = u_xlat3.xyz * vec3(0.300000012, 0.300000012, 0.300000012);
    u_xlat3.xyz = fract(u_xlat1.xyz);
    u_xlat3.xyz = (-u_xlat3.xyz) + vec3(0.5, 0.5, 0.5);
    u_xlat19 = dot(u_xlat3.xyz, u_xlat3.xyz);
    u_xlat19 = sqrt(u_xlat19);
    u_xlat18 = min(u_xlat18, u_xlat19);
    u_xlat3.x = dot(u_xlat1.xyz, vec3(-2.0, 3.0, 1.0));
    u_xlat3.y = dot(u_xlat1.xyz, vec3(-1.0, -2.0, 2.0));
    u_xlat3.z = dot(u_xlat1.xzy, vec3(2.0, 2.0, 1.0));
    u_xlat1.xyz = u_xlat3.xyz * vec3(0.200000003, 0.200000003, 0.200000003);
    u_xlat1.xyz = fract(u_xlat1.xyz);
    u_xlat1.xyz = (-u_xlat1.xyz) + vec3(0.5, 0.5, 0.5);
    u_xlat1.x = dot(u_xlat1.xyz, u_xlat1.xyz);
    u_xlat1.x = sqrt(u_xlat1.x);
    u_xlat18 = min(u_xlat18, u_xlat1.x);
    u_xlat1.x = _strength * 0.100000001;
    u_xlat1.x = float(1.0) / u_xlat1.x;
    u_xlat18 = log2(u_xlat18);
    u_xlat18 = u_xlat18 * u_xlat1.x;
    u_xlat18 = exp2(u_xlat18);
    u_xlat18 = u_xlat18 * _intensity;
    u_xlat18 = u_xlat18 * 10.0;
    u_xlat1.xy = u_xlat2.xy * vec2(u_xlat18);
    u_xlat1.x = u_xlat1.y + u_xlat1.x;
    u_xlat1.x = u_xlat18 * u_xlat2.z + u_xlat1.x;
    u_xlat1.x = u_xlat1.x * 0.333333343;
    u_xlat7.xyz = vec3(u_xlat18) * u_xlat2.xyz + (-u_xlat1.xxx);
    u_xlat1.xyz = vec3(vec3(_dispersion, _dispersion, _dispersion)) * u_xlat7.xyz + u_xlat1.xxx;
    u_xlat0.xyz = _background_color.xyz * u_xlat0.xyz + u_xlat1.xyz;
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlatb2.x = int(_blend_mode)==1;
    u_xlat0.w = 1.0;
    u_xlat3 = u_xlat0 * u_xlat1;
    u_xlat4.xyz = u_xlat0.xyz + u_xlat1.xyz;
    u_xlat4.w = u_xlat1.w;
    u_xlat2 = (u_xlatb2.x) ? u_xlat3 : u_xlat4;
    u_xlat4.xyz = u_xlat0.xyz;
    u_xlat0 = (int(_blend_mode) != 0) ? u_xlat2 : u_xlat4;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
